/**
 * Centerline radius of the logarithmic spiral:
 *   r(theta) = exp(growth * theta)
 * Self-similar: r(theta + 2*PI) / r(theta) === exp(growth * 2*PI).
 */
export function centerlineRadius(theta, growth = 0.18) {
  return Math.exp(growth * theta);
}

/**
 * Builds a seashell surface by sweeping a circular cross-section of radius
 * tubeRatio * r(theta) along a logarithmic spiral
 *   r(theta) = exp(growth * theta),  theta in [0, turns * 2*PI],
 * rising in y proportionally to theta.
 *
 * Returns a THREE.BufferGeometry with (segU + 1) * (segV + 1) vertices and
 * an index buffer; call computeVertexNormals() on it for smooth shading.
 */
export function shellGeometry({
  turns = 3,
  growth = 0.18,
  tubeRatio = 0.35,
  segU = 200,
  segV = 16,
} = {}) {
  const thetaMax = turns * Math.PI * 2;
  // Vertical rise per unit theta (proportional to theta along the sweep).
  const yPerTheta = 0.25;

  const positions = new Float32Array((segU + 1) * (segV + 1) * 3);
  const uvs = new Float32Array((segU + 1) * (segV + 1) * 2);

  for (let i = 0; i <= segU; i++) {
    const u = i / segU;
    const theta = u * thetaMax;
    const r = centerlineRadius(theta, growth);
    const cx = r * Math.cos(theta);
    const cz = r * Math.sin(theta);
    const cy = yPerTheta * theta;
    const tubeR = tubeRatio * r;

    for (let j = 0; j <= segV; j++) {
      const v = j / segV;
      const phi = v * Math.PI * 2;
      // Local frame: radial outward in the xz-plane, plus world up.
      const nx = Math.cos(theta);
      const nz = Math.sin(theta);
      const px = cx + tubeR * (nx * Math.cos(phi));
      const py = cy + tubeR * Math.sin(phi);
      const pz = cz + tubeR * (nz * Math.cos(phi));

      const k = i * (segV + 1) + j;
      positions[k * 3 + 0] = px;
      positions[k * 3 + 1] = py;
      positions[k * 3 + 2] = pz;
      uvs[k * 2 + 0] = u;
      uvs[k * 2 + 1] = v;
    }
  }

  const indices = [];
  for (let i = 0; i < segU; i++) {
    for (let j = 0; j < segV; j++) {
      const a = i * (segV + 1) + j;
      const b = a + segV + 1;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }

  const geometry = new BufferGeometry();
  geometry.setAttribute('position', new BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new BufferAttribute(uvs, 2));
  geometry.setIndex(indices);

  return geometry;
}
