result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/shell.test.js", "content": "import { describe, it, expect } from 'vitest';
import { Box3, Vector3 } from 'three';
import { shellGeometry, centerlineRadius } from '../src/shell.js';

describe('centerlineRadius', () => {
  it('is strictly increasing over 50 samples', () => {
    const growth = 0.18;
    let prev = -Infinity;
    for (let i = 0; i <= 50; i++) {
      const theta = (i / 50) * 3 * Math.PI * 2;
      const r = centerlineRadius(theta, growth);
      expect(r).toBeGreaterThan(prev);
      prev = r;
    }
  });

  it('is self-similar: r(theta + 2PI)/r(theta) == exp(growth*2PI) within 1e-9', () => {
    const growth = 0.18;
    const expected = Math.exp(growth * 2 * Math.PI);
    for (const theta of [0, 0.7, Math.PI / 2, 2.13, Math.PI, 4.99]) {
      const ratio =
        centerlineRadius(theta + 2 * Math.PI, growth) /
        centerlineRadius(theta, growth);
      expect(Math.abs(ratio - expected)).toBeLessThan(1e-9);
    }
  });
});

describe('shellGeometry', () => {
  it('has (segU+1)*(segV+1) vertices', () => {
    const params = { turns: 3, growth: 0.18, tubeRatio: 0.35, segU: 200, segV: 16 };
    const geo = shellGeometry(params);
    expect(geo.attributes.position.count).toBe(
      (params.segU + 1) * (params.segV + 1)
    );
  });

  it('Box3 grows monotonically with turns', () => {
    const box2 = new Box3().setFromBufferAttribute(
      shellGeometry({ turns: 2 }).attributes.position
    );
    const box3 = new Box3().setFromBufferAttribute(
      shellGeometry({ turns: 3 }).attributes.position
    );
    const size2 = new Vector3();
    const size3 = new Vector3();
    box2.getSize(size2);
    box3.getSize(size3);
    expect(size3.x).toBeGreaterThanOrEqual(size2.x);
    expect(size3.y).toBeGreaterThanOrEqual(size2.y);
    expect(size3.z).toBeGreaterThanOrEqual(size2.z);
    // Strictly larger overall, not just equal.
    expect(size3.length()).toBeGreaterThan(size2.length());
  });

  it('has all unit-length normals within 1e-3 after computeVertexNormals', () => {
    const geo = shellGeometry({ turns: 3 });
    geo.computeVertexNormals();
    const normals = geo.attributes.normal;
    for (let i = 0; i < normals.count; i++) {
      const len = Math.hypot(
        normals.getX(i),
        normals.getY(i),
        normals.getZ(i)
      );
      expect(Math.abs(len - 1)).toBeLessThan(1e-3);
    }
  });
});
"})
